struct VaParts { unsigned pml4, pdpt, pd, pt, offset; };

bool split_va(uint64_t va, VaParts& out) {
  // Canonical: bits 63..47 are all copies of bit 47.
  uint64_t top = va >> 47;
  if (top != 0 && top != 0x1FFFF) return false;
  out.pml4   = (va >> 39) & 0x1FF;
  out.pdpt   = (va >> 30) & 0x1FF;
  out.pd     = (va >> 21) & 0x1FF;
  out.pt     = (va >> 12) & 0x1FF;
  out.offset = va & 0xFFF;
  return true;
}

